/// Estimate model weight memory in bytes.
/// Approximate: params * dtype_bytes (bf16 = 2 bytes, fp16/fp32 = 2/4 bytes)
fn estimate_model_memory_bytes(config: &ModelConfig) -> u64 {
    let dtype_bytes = match config.dtype {
        DType::BF16 | DType::FP16 => 2,
        DType::FP32 => 4,
    };
    // 4B params * 2 bytes = 8GB for Qwen3.5-4B
    (config.hidden_size as f64 * config.num_layers as f64 * config.hidden_size as f64
        * dtype_bytes as f64) as u64 / 1024 / 1024 / 1024
        * 8
        * 1024
        * 1024
}

